describe("refreshPrices", () => {
  const mkLine = (id: string, price: number, qty = 1): CartLine => ({
    product: { id, name: id, unitPriceCents: price },
    quantity: qty,
  });

  it("updates unitPriceCents from fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(200)
        .mockResolvedValueOnce(300),
    };
    const lines = [mkLine("a", 100, 2), mkLine("b", 150, 1)];
    const result = await refreshPrices(lines, fetcher);

    expect(result).toHaveLength(2);
    expect(result[0]!.product.unitPriceCents).toBe(200);
    expect(result[0]!.quantity).toBe(2);
    expect(result[1]!.product.unitPriceCents).toBe(300);
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("b");
  });

  it("preserves other product fields", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(500),
    };
    const lines: CartLine[] = [
      {
        product: { id: "x", name: "Widget", unitPriceCents: 100, weightGrams: 250, currency: "EUR" },
        quantity: 1,
      },
    ];
    const result = await refreshPrices(lines, fetcher);
    expect(result[0]!.product.name).toBe("Widget");
    expect(result[0]!.product.weightGrams).toBe(250);
    expect(result[0]!.product.currency).toBe("EUR");
  });

  it("throws RangeError for negative price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-1),
    };
    await expect(refreshPrices([mkLine("a", 100)], fetcher)).rejects.toThrow(RangeError);
  });

  it("throws RangeError for non-integer price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };
    await expect(refreshPrices([mkLine("a", 100)], fetcher)).rejects.toThrow(RangeError);
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch failed")),
    };
    await expect(refreshPrices([mkLine("a", 100)], fetcher)).rejects.toThrow("fetch failed");
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };
    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });
});

import { describe, it, expect, vi, beforeEach } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import { InventoryError } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

const product = (
  id: string,
  unitPriceCents: number,
  weightGrams?: number,
): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents,
  weightGrams,
});

describe("Cart — line management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  it("starts empty", () => {
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("adds a product", () => {
    cart.add(product("a", 100), 2);
    expect(cart.itemCount).toBe(2);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0]!.product.id).toBe("a");
    expect(snap[0]!.quantity).toBe(2);
  });

  it("merges quantity when adding the same product twice", () => {
    cart.add(product("a", 100), 2);
    cart.add(product("a", 100), 3);
    expect(cart.itemCount).toBe(5);
    expect(cart.snapshot()).toHaveLength(1);
  });

  it("rejects non-positive quantity on add", () => {
    expect(() => cart.add(product("a", 100), 0)).toThrow(RangeError);
    expect(() => cart.add(product("a", 100), -1)).toThrow(RangeError);
  });

  it("rejects non-integer quantity on add", () => {
    expect(() => cart.add(product("a", 100), 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents on add", () => {
    expect(() => cart.add(product("a", -1), 1)).toThrow(RangeError);
  });

  it("removes a product and returns true", () => {
    cart.add(product("a", 100), 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false when removing unknown product", () => {
    expect(cart.remove("unknown")).toBe(false);
  });

  it("updates quantity", () => {
    cart.add(product("a", 100), 2);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("removes line when updating quantity to 0", () => {
    cart.add(product("a", 100), 2);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toHaveLength(0);
  });

  it("throws when updating quantity for unknown product", () => {
    expect(() => cart.updateQuantity("unknown", 1)).toThrow(
      "Product unknown is not in the cart",
    );
  });

  it("rejects negative quantity on update", () => {
    cart.add(product("a", 100), 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("rejects non-integer quantity on update", () => {
    cart.add(product("a", 100), 1);
    expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
  });

  it("clears all lines", () => {
    cart.add(product("a", 100), 1);
    cart.add(product("b", 200), 3);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("snapshot returns a deep copy", () => {
    cart.add(product("a", 100), 1);
    const snap = cart.snapshot();
    snap[0]!.quantity = 999;
    snap[0]!.product.unitPriceCents = 0;
    // original cart unchanged
    expect(cart.snapshot()[0]!.quantity).toBe(1);
    expect(cart.snapshot()[0]!.product.unitPriceCents).toBe(100);
  });
});

describe("Cart — totals (pricing pipeline)", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 500), 2);
    cart.add(product("b", 300), 3);
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(1900); // 500*2 + 300*3
  });

  it("returns all-zero totals for empty cart", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("clamps discount to [0, subtotal]", () => {
    const overDiscount: DiscountPolicy = {
      computeDiscountCents: () => 99999,
    };
    const cart = new Cart({ discountPolicy: overDiscount });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().discountCents).toBe(1000);
    expect(cart.totals().totalCents).toBeGreaterThanOrEqual(0);
  });

  it("clamps negative discount to 0", () => {
    const negDiscount: DiscountPolicy = {
      computeDiscountCents: () => -500,
    };
    const cart = new Cart({ discountPolicy: negDiscount });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("applies tax on the discounted subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: (s) => Math.floor(s * 0.1), // 10%
    };
    const tax: TaxCalculator = {
      computeTaxCents: (taxable, _region) => Math.floor(taxable * 0.08),
    };
    const cart = new Cart({ discountPolicy: discount, taxCalculator: tax });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    // subtotal=1000, discount=100, discounted=900, tax=8% of 900=72
    expect(totals.subtotalCents).toBe(1000);
    expect(totals.discountCents).toBe(100);
    expect(totals.taxCents).toBe(72);
  });

  it("passes discounted subtotal to shipping calculator", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: () => 500,
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: (_lines, subtotalCents) => {
        return subtotalCents >= 1000 ? 0 : 599;
      },
    };
    const cart = new Cart({ discountPolicy: discount, shippingCalculator: shipping });
    cart.add(product("a", 1200), 1);
    // discounted = 1200 - 500 = 700 < 1000 → shipping = 599
    expect(cart.totals().shippingCents).toBe(599);
  });

  it("computes totalCents = discountedSubtotal + tax + shipping", () => {
    const discount: DiscountPolicy = { computeDiscountCents: () => 200 };
    const tax: TaxCalculator = { computeTaxCents: () => 80 };
    const shipping: ShippingCalculator = { computeShippingCents: () => 500 };
    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
      shippingCalculator: shipping,
    });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    expect(totals.totalCents).toBe(800 + 80 + 500); // 1380
  });

  it("clamps negative tax to 0", () => {
    const tax: TaxCalculator = { computeTaxCents: () => -50 };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shipping: ShippingCalculator = { computeShippingCents: () => -50 };
    const cart = new Cart({ shippingCalculator: shipping });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("uses configured region for tax calculation", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: tax, region: "FR" });
    cart.add(product("a", 1000), 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
  });

  it("defaults region to US", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(product("a", 1000), 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(1000, "US");
  });
});

describe("Cart — checkout()", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
    cart.add(product("a", 1000), 2);
  });

  it("returns totals and lines without collaborators", async () => {
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.lines).toHaveLength(1);
  });

  it("refreshes prices from priceFetcher", async () => {
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher });
    // refreshed price: 1500 * 2 = 3000
    expect(result.totals.subtotalCents).toBe(3000);
    expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
  });

  it("propagates priceFetcher rejection", async () => {
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow("price service down");
  });

  it("passes inventory check when available", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
    expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
  });

  it("throws InventoryError when item is unavailable", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        reason: "out of stock",
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(2);
      expect(invErr.message).toBe("out of stock");
    }
  });

  it("throws InventoryError for partial-stock denial", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 1,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(2);
      expect(invErr.available).toBe(1);
    }
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const cart = new Cart({ region: "US" });
    cart.add(product("a", 1000), 1);
    const result = await cart.checkout({ asyncTaxProvider });
    // 10% of 1000 = 100
    expect(result.totals.taxCents).toBe(100);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
  });

  it("async tax provider failure propagates", async () => {
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow("tax service down");
  });

  it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
    const discount: DiscountPolicy = { computeDiscountCents: () => 200 };
    const shipping: ShippingCalculator = { computeShippingCents: () => 500 };
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
      region: "US-CA",
    });
    cart.add(product("x", 500), 2);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(600),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };

    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });

    // refreshed price: 600 * 2 = 1200
    expect(result.totals.subtotalCents).toBe(1200);
    // discount: 200, discounted = 1000
    expect(result.totals.discountCents).toBe(200);
    // tax: 8.75% of 1000 = 87.5 → 87
    expect(result.totals.taxCents).toBe(87);
    // shipping: 500
    expect(result.totals.shippingCents).toBe(500);
    // total: 1000 + 87 + 500 = 1587
    expect(result.totals.totalCents).toBe(1587);
  });

  it("first inventory denial wins when multiple items fail", async () => {
    const cart = new Cart();
    cart.add(product("a", 100), 5);
    cart.add(product("b", 200), 3);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn()
        .mockResolvedValueOnce({ available: false, reason: "a out of stock" })
        .mockResolvedValueOnce({ available: false, reason: "b out of stock" }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      // Only the first item should have been checked before throwing
      expect((err as InventoryError).productId).toBe("a");
    }
  });

  it("inventory check uses default message when no reason given", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 0,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      expect((err as InventoryError).message).toContain("insufficient stock");
    }
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([0, 100, 10000, -50])("returns 0 for subtotal %i", (subtotal) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, 101, NaN, Infinity, -Infinity])(
      "rejects invalid percent %s",
      (p) => {
        expect(() => new PercentageDiscountPolicy(p)).toThrow(RangeError);
      },
    );

    it.each([0, 50, 100])("accepts valid percent %i", (p) => {
      expect(() => new PercentageDiscountPolicy(p)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 1000 = 100", () => {
      expect(new PercentageDiscountPolicy(10).computeDiscountCents(1000)).toBe(100);
    });

    it("rounds down (floors) the result", () => {
      // 15% of 999 = 149.85 → 149
      expect(new PercentageDiscountPolicy(15).computeDiscountCents(999)).toBe(149);
    });

    it("returns 0 for zero subtotal", () => {
      expect(new PercentageDiscountPolicy(50).computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      expect(new PercentageDiscountPolicy(50).computeDiscountCents(-100)).toBe(0);
    });

    it("100% discount equals the subtotal", () => {
      expect(new PercentageDiscountPolicy(100).computeDiscountCents(5000)).toBe(5000);
    });

    it("0% discount returns 0", () => {
      expect(new PercentageDiscountPolicy(0).computeDiscountCents(5000)).toBe(0);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, -100])("rejects negative amountCents %i", (a) => {
      expect(() => new FixedAmountDiscountPolicy(a)).toThrow(RangeError);
    });

    it("rejects non-integer amountCents", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts 0", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns the fixed amount when subtotal is larger", () => {
      expect(new FixedAmountDiscountPolicy(500).computeDiscountCents(1000)).toBe(500);
    });

    it("caps at the subtotal when fixed amount exceeds it", () => {
      expect(new FixedAmountDiscountPolicy(2000).computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      expect(new FixedAmountDiscountPolicy(500).computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      expect(new FixedAmountDiscountPolicy(500).computeDiscountCents(-100)).toBe(0);
    });

    it("returns subtotal when amount equals subtotal exactly", () => {
      expect(new FixedAmountDiscountPolicy(1000).computeDiscountCents(1000)).toBe(1000);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against the original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 1000 = 100, plus fixed 200 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("clamps negative child results to 0 before summing", () => {
      const negativePolicy = { computeDiscountCents: () => -50 };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      // max(0, -50) + 100 = 100
      expect(composite.computeDiscountCents(1000)).toBe(100);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("can exceed subtotal (caller is responsible for clamping)", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(600), new FixedAmountDiscountPolicy(600)],
        "sum",
      );
      // FixedAmount caps each at subtotal, so 1000 + 1000 = 2000
      expect(composite.computeDiscountCents(1000)).toBe(2000);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // 10% of 1000 = 100, remaining = 900; 10% of 900 = 90; total = 190
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("ordering matters in chain mode", () => {
      const bigFirst = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(800), new PercentageDiscountPolicy(50)],
        "chain",
      );
      const smallFirst = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new FixedAmountDiscountPolicy(800)],
        "chain",
      );
      // bigFirst: fixed 800 off 1000 → remaining 200; 50% of 200 = 100; total = 900
      expect(bigFirst.computeDiscountCents(1000)).toBe(900);
      // smallFirst: 50% of 1000 = 500 → remaining 500; fixed 800 capped at 500; total = 1000
      expect(smallFirst.computeDiscountCents(1000)).toBe(1000);
    });

    it("stops compounding when remaining reaches 0", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(1000),
          new PercentageDiscountPolicy(50),
        ],
        "chain",
      );
      // fixed 1000 wipes out subtotal; remaining = 0; 50% of 0 = 0; total = 1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("clamps negative child results to 0", () => {
      const negativePolicy = { computeDiscountCents: () => -100 };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // max(0, -100) = 0; then fixed 200 from remaining 1000 = 200; total = 200
      expect(composite.computeDiscountCents(1000)).toBe(200);
    });
  });

  it("defaults to sum mode", () => {
    const composite = new CompositeDiscountPolicy([
      new FixedAmountDiscountPolicy(100),
      new FixedAmountDiscountPolicy(200),
    ]);
    // sum: min(100,1000) + min(200,1000) = 300
    expect(composite.computeDiscountCents(1000)).toBe(300);
  });
});

