describe("Cart — totals (pricing pipeline)", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 500), 2);
    cart.add(product("b", 300), 3);
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(1900); // 500*2 + 300*3
  });

  it("returns all-zero totals for empty cart", () => {
    const cart = new Cart();
