    cart.add(product("a", 100), 3);
    expect(cart.itemCount).toBe(5);
    expect(cart.snapshot()).toHaveLength(1);
  });

  it("rejects non-positive quantity on add", () => {
    expect(() => cart.add(product("a", 100), 0)).toThrow(RangeError);
    expect(() => cart.add(product("a", 100), -1)).toThrow(RangeError);
  });

  it("rejects non-integer quantity on add", () => {
    expect(() => cart.add(product("a", 100), 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents on add", () => {
    expect(() => cart.add(product("a", -1), 1)).toThrow(RangeError);
  });

  it("removes a product and returns true", () => {
    cart.add(product("a", 100), 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false when removing unknown product", () => {
    expect(cart.remove("unknown")).toBe(false);
  });

  it("updates quantity", () => {
    cart.add(product("a", 100), 2);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("removes line when updating quantity to 0", () => {
    cart.add(product("a", 100), 2);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toHaveLength(0);
  });

  it("throws when updating quantity for unknown product", () => {
    expect(() => cart.updateQuantity("unknown", 1)).toThrow(
      "Product unknown is not in the cart",
    );
  });

  it("rejects negative quantity on update", () => {
    cart.add(product("a", 100), 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("rejects non-integer quantity on update", () => {
    cart.add(product("a", 100), 1);
    expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
  });

  it("clears all lines", () => {
    cart.add(product("a", 100), 1);
    cart.add(product("b", 200), 3);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("snapshot returns a deep copy", () => {
    cart.add(product("a", 100), 1);
    const snap = cart.snapshot();
    snap[0]!.quantity = 999;
    snap[0]!.product.unitPriceCents = 0;
    // original cart unchanged
    expect(cart.snapshot()[0]!.quantity).toBe(1);
    expect(cart.snapshot()[0]!.product.unitPriceCents).toBe(100);
  });
});

describe("Cart — totals (pricing pipeline)", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 500), 2);
    cart.add(product("b", 300), 3);
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(1900); // 500*2 + 300*3
  });

  it("returns all-zero totals for empty cart", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("clamps discount to [0, subtotal]", () => {
    const overDiscount: DiscountPolicy = {
      computeDiscountCents: () => 99999,
    };
    const cart = new Cart({ discountPolicy: overDiscount });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().discountCents).toBe(1000);
    expect(cart.totals().totalCents).toBeGreaterThanOrEqual(0);
  });

  it("clamps negative discount to 0", () => {
    const negDiscount: DiscountPolicy = {
      computeDiscountCents: () => -500,
    };
    const cart = new Cart({ discountPolicy: negDiscount });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("applies tax on the discounted subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: (s) => Math.floor(s * 0.1), // 10%
    };
    const tax: TaxCalculator = {
      computeTaxCents: (taxable, _region) => Math.floor(taxable * 0.08),
    };
    const cart = new Cart({ discountPolicy: discount, taxCalculator: tax });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    // subtotal=1000, discount=100, discounted=900, tax=8% of 900=72
    expect(totals.subtotalCents).toBe(1000);
    expect(totals.discountCents).toBe(100);
    expect(totals.taxCents).toBe(72);
  });

  it("passes discounted subtotal to shipping calculator", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: () => 500,
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: (_lines, subtotalCents) => {
        return subtotalCents >= 1000 ? 0 : 599;
      },
    };
    const cart = new Cart({ discountPolicy: discount, shippingCalculator: shipping });
    cart.add(product("a", 1200), 1);
    // discounted = 1200 - 500 = 700 < 1000 → shipping = 599
    expect(cart.totals().shippingCents).toBe(599);
  });

  it("computes totalCents = discountedSubtotal + tax + shipping", () => {
    const discount: DiscountPolicy = { computeDiscountCents: () => 200 };
    const tax: TaxCalculator = { computeTaxCents: () => 80 };
    const shipping: ShippingCalculator = { computeShippingCents: () => 500 };
    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
      shippingCalculator: shipping,
    });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    expect(totals.totalCents).toBe(800 + 80 + 500); // 1380
  });

  it("clamps negative tax to 0", () => {
    const tax: TaxCalculator = { computeTaxCents: () => -50 };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shipping: ShippingCalculator = { computeShippingCents: () => -50 };
    const cart = new Cart({ shippingCalculator: shipping });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("uses configured region for tax calculation", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: tax, region: "FR" });
    cart.add(product("a", 1000), 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
  });

  it("defaults region to US", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(product("a", 1000), 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(1000, "US");
  });
});

describe("Cart — checkout()", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
    cart.add(product("a", 1000), 2);
  });

  it("returns totals and lines without collaborators", async () => {
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.lines).toHaveLength(1);
  });

  it("refreshes prices from priceFetcher", async () => {
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher });
    // refreshed price: 1500 * 2 = 3000
    expect(result.totals.subtotalCents).toBe(3000);
    expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
  });

  it("propagates priceFetcher rejection", async () => {
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow("price service down");
  });

  it("passes inventory check when available", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
    expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
  });

  it("throws InventoryError when item is unavailable", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        reason: "out of stock",
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(2);
      expect(invErr.message).toBe("out of stock");
    }
  });

  it("throws InventoryError for partial-stock denial", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 1,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(2);
      expect(invErr.available).toBe(1);
    }
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const cart = new Cart({ region: "US" });
    cart.add(product("a", 1000), 1);
    const result = await cart.checkout({ asyncTaxProvider });
    // 10% of 1000 = 100
    expect(result.totals.taxCents).toBe(100);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
  });

  it("async tax provider failure propagates", async () => {
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow("tax service down");
  });

  it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
    const discount: DiscountPolicy = { computeDiscountCents: () => 200 };
    const shipping: ShippingCalculator = { computeShippingCents: () => 500 };
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
      region: "US-CA",
    });
    cart.add(product("x", 500), 2);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(600),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };

    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });

    // refreshed price: 600 * 2 = 1200
    expect(result.totals.subtotalCents).toBe(1200);
    // discount: 200, discounted = 1000
    expect(result.totals.discountCents).toBe(200);
    // tax: 8.75% of 1000 = 87.5 → 87
    expect(result.totals.taxCents).toBe(87);
    // shipping: 500
    expect(result.totals.shippingCents).toBe(500);
    // total: 1000 + 87 + 500 = 1587
    expect(result.totals.totalCents).toBe(1587);
  });

  it("first inventory denial wins when multiple items fail", async () => {
    const cart = new Cart();
    cart.add(product("a", 100), 5);
    cart.add(product("b", 200), 3);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn()
        .mockResolvedValueOnce({ available: false, reason: "a out of stock" })
        .mockResolvedValueOnce({ available: false, reason: "b out of stock" }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      // Only the first item should have been checked before throwing
      expect((err as InventoryError).productId).toBe("a");
    }
  });

  it("inventory check uses default message when no reason given", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 0,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      expect((err as InventoryError).message).toContain("insufficient stock");
    }
  });
});
"}
